// Optimal file merge (greedy): always merge the two smallest files first.
function minMergeCost(files) {
  const heap = [...files];
  let cost = 0;
  while (heap.length > 1) {
    heap.sort((a, b) => a - b);
    const a = heap.shift();
    const b = heap.shift();
    const merged = a + b;
    cost += merged;
    heap.push(merged);
  }
  return cost;
}

