import java.util.*;
public class OptimalFileMerge {
    public static long minCost(int[] files) {
        PriorityQueue<Long> pq = new PriorityQueue<>();
        for (int f : files) pq.add((long)f);
        long totalCost = 0;
        while (pq.size() > 1) {
            long a = pq.poll(), b = pq.poll();
            totalCost += a + b;
            pq.add(a + b);
        }
        return totalCost;
    }
    public static void main(String[] args) {
        int[] files = {2, 3, 4, 5, 6};
        System.out.println("Minimum merge cost: " + minCost(files));
    }
}

