long minMergeCost(int* files, int n) {
    /* Use min-heap — simplified with sorted array for small n */
    long total=0, arr[100]; for(int i=0;i<n;i++) arr[i]=files[i];
    for(int cnt=n;cnt>1;cnt--) {
        /* sort and take two smallest */
        for(int i=0;i<cnt-1;i++) for(int j=0;j<cnt-i-1;j++) if(arr[j]>arr[j+1]){long t=arr[j];arr[j]=arr[j+1];arr[j+1]=t;}
        long m=arr[0]+arr[1]; total+=m;
        arr[0]=m; for(int i=1;i<cnt-1;i++) arr[i]=arr[i+1]; cnt--;
    }
    return total;
}

