#include <bits/stdc++.h>
using namespace std;
long long minMergeCost(vector<int>& files) {
    priority_queue<long long, vector<long long>, greater<long long>> pq(files.begin(), files.end());
    long long total = 0;
    while (pq.size() > 1) {
        auto a = pq.top(); pq.pop();
        auto b = pq.top(); pq.pop();
        total += a + b; pq.push(a + b);
    }
    return total;
}
